const updateReviewMessageBody = `-- name: UpdateReviewMessageBody :one
WITH written AS (
    UPDATE
        review_messages m
    SET
        body = $1,
        suggestion = $2
    WHERE
        m.id = $3
    RETURNING
        id, thread_id, author_kind, author_agent_id, body, created_at, updated_at, review_id, suggestion
),
touched AS (
    UPDATE
        review_threads t
    SET
        last_agent_activity_at = CASE WHEN w.author_kind = 'agent' THEN
            NOW()
        ELSE
            t.last_agent_activity_at
        END,
        resolved_at = NULL
    FROM
        written w
    WHERE
        t.id = w.thread_id
    RETURNING
        t.id
)
SELECT
    w.id, w.thread_id, w.author_kind, w.author_agent_id, w.body, w.created_at, w.updated_at, w.review_id, w.suggestion
FROM
    written w
`

type UpdateReviewMessageBodyParams struct {
	Body       string
	Suggestion []string
	ID         string
}

type UpdateReviewMessageBodyRow struct {
	ID            string
	ThreadID      string
	AuthorKind    ReviewAuthorKind
	AuthorAgentID *string
	Body          string
	CreatedAt     time.Time
	UpdatedAt     time.Time
	ReviewID      *string
	Suggestion    []string
}

func (q *Queries) UpdateReviewMessageBody(ctx context.Context, arg UpdateReviewMessageBodyParams) (*UpdateReviewMessageBodyRow, error) {
	row := q.db.QueryRow(ctx, updateReviewMessageBody, arg.Body, arg.Suggestion, arg.ID)
	var i UpdateReviewMessageBodyRow
	err := row.Scan(
		&i.ID,
		&i.ThreadID,
		&i.AuthorKind,
		&i.AuthorAgentID,
		&i.Body,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ReviewID,
		&i.Suggestion,
	)
	return &i, err
}
